	sections = {
		{
			title = "Summary",
			text = [=[Mystral Lake is a broad water in southern {link:ashenvale}Ashenvale{/link}, near the mouth of the {link:the-talondeep-path}Talondeep Path{/link} that leads into the {link:stonetalon-mountains}Stonetalon Mountains{/link}. Its waters have come alive. Befouled elementals rise from them and attack anything that comes near, and the road between the forest and Stonetalon is all but closed. A gazebo on the lake looks out over the elven refuge on its shore, and both the {link:sentinels}Sentinels{/link} and the {link:horde}Horde{/link} have taken an interest in who watches from it. On the southern shore lives {link:krolg}Krolg{/link}, a {link:furbolgs}furbolg{/link} who has escaped the corruption of his kin.]=],
		},
	},
})

