	sections = {
		{
			title = "Summary",
			text = [=[The Warsong Lumber Camp lies in the far east of {link:ashenvale}Ashenvale{/link}, near the river that divides the forest from {link:azshara}Azshara{/link}. Here the peons of the Warsong clan fell the great trees of the elves and send the timber south to build and fuel the {link:horde}Horde{/link}. Goblin shredders roar among the stumps, and grunts guard the workers from Sentinel arrows. This is the labor that brought {link:grom-hellscream}Grom Hellscream{/link} to Ashenvale in the {link:third-war}Third War{/link}, and it has never stopped. The camp lives on supplies: saw blades from {link:ratchet}Ratchet{/link}, axes from {link:booty-bay}Booty Bay{/link}, oil and rope that the satyrs and furbolgs keep stealing.]=],
