			unlock = {
				{ type = "quest", id = 991 },
				{ type = "quest", id = 1023 },
			},
			text = [=[Raene's friend {link:teronis}Teronis{/link} went west to {link:lake-falathim}Lake Falathim{/link} in search of a gem, and he did not return. He had been hunting the pieces of a rod made by a dead wizard, Dartol, which he believed could slow the {link:furbolgs}furbolg{/link} attacks. His body was found on the island, slashed by {link:murlocs}murloc{/link} claws. Raene put aside her grief. The time for mourning would come later. What mattered now was that his work not be wasted.]=],
