			key = "dartol-s-rod",
			title = "Dartol's Rod",
			hint = [=[Gather the pieces of the rod and seek the dryad at the moonwell.]=],
			unlock = {
				{ type = "quest", id = 1024 },
				{ type = "quest", id = 1029 },
			},
			text = [=[From the notes in {link:teronis}Teronis{/link}'s journal, the pieces of Dartol's rod were traced across the forest: one guarded by corrupted treants near {link:felwood}Felwood{/link}, one hidden with the doomed druids of {link:the-dor-danil-barrow-den}Dor'Danil{/link}. The dryad {link:shael-dryn}Shael'dryn{/link} joined them together, and a hidden shrine gave the rod its power again. It could lend its bearer the shape of a {link:furbolgs}furbolg{/link}. Raene did not know what Teronis had meant to do with it. She guessed that he hoped to speak with a furbolg still untouched by the Fel Moss.]=],
