			hint = "Learn what the uncorrupted furbolg asks of his own kind.",
			unlock = {
				{ type = "quest", id = 1046 },
			},
			text = [=[The rod led to {link:krolg}Krolg{/link}, a {link:furbolgs}furbolg{/link} who had escaped the corruption, and who blamed the elves for all that had befallen his people. Yet Krolg would not see elven children suffer for it. He asked that his kind police their own, and so {link:ran-bloodtooth}Ran Bloodtooth{/link}, the fiercest of the corrupted furbolgs, was slain. Raene set his skull and Dartol's rod where all of {link:astranaar}Astranaar{/link} could see them, and said that {link:teronis}Teronis{/link} would be proud.]=],
		},
	},
	mentions = {
